package org.eclipse.rdf4j.sail.lmdb.evaluation.fragment;

/**
 * A compiled predicate fragment: any backend (interpreter-backed, precompiled primitive, generated class) exposing the
 * uniform scalar entry point. Implementations are immutable and stateless; all query-specific data arrives through the
 * binding, so one compiled fragment instance serves every query sharing its shape.
 */
public interface LongPredicateFragment {

	/** Evaluates the predicate over up to three argument ids; unused trailing arguments are {@code -1}. */
	PredicateStatus test(long a0, long a1, long a2, FragmentBinding binding);

	/** Filter-site evaluation: ESCAPE resolved through the binding's exact fallback, ERROR folded to reject. */
	default boolean testAtFilterSite(long a0, long a1, long a2, FragmentBinding binding) {
		PredicateStatus status = test(a0, a1, a2, binding);
		if (status == PredicateStatus.ESCAPE) {
			return binding.escapeToExact(a0, a1, a2);
		}
		return status == PredicateStatus.TRUE;
	}
}
